import { GraphRAG } from 'graph-rag-library';

export class KnowledgeGraphUpdater {
  constructor() {
    this.graph = new GraphRAG();
  }

  updateGraph(newData) {
    newData.forEach(dataPoint => {
      this.graph.addNode(dataPoint.id, dataPoint.content);
      dataPoint.relationships.forEach(rel => {
        this.graph.addEdge(dataPoint.id, rel.targetId, rel.type);
      });
    });
  }

  retrieveDynamicEmbeddings(query) {
    return this.graph.query(query);
  }
}